// Phase 2 of focus + tasks inbox brief: classify a raw inbox row.
// The inbox_id gate runs first, as it always did; the three reads and writes
// that follow are HTTP Request nodes on the stored Supabase credential (moved
// out of this node's source on 2026-10-03, with the service-role key).
const input = $input.first().json;
const body = input.body || input;
const inbox_id = body.inbox_id;
if (!inbox_id) throw new Error('inbox_id required');
return [{ json: { inbox_id } }];

// Builds the classifier prompt. "Mark classifying", "Fetch inbox row" and
// "Fetch active agents" ran before this over the stored Supabase credential.
const inbox_id = $('Check inbox id').first().json.inbox_id;
const fetched = $('Fetch inbox row').first().json.body;
const row = (Array.isArray(fetched) ? fetched : [])[0];
if (!row) throw new Error('inbox row not found');

// A failed agents read used to fall back to an empty list; its node continues
// on error, so the same fallback applies.
const agentsBody = $('Fetch active agents').first().json.body;
const agents = Array.isArray(agentsBody) ? agentsBody : [];
const agentList = (agents || []).map(a => `${a.id} (${a.pod}/${a.role})`).join('; ');

const system = [
  'You route a raw task Krish dropped into his inbox to the right OS surface. Output strict JSON.',
  'Pick exactly ONE primary_agent from the active fleet (' + agentList + ').',
  'Pick exactly ONE target_table from: tasks, leads, visibility_targets, guests, content_ideas, bets, customers.',
  'Common mappings:',
  '  follow-up / personal todo / decision deferred -> tasks (any agent)',
  '  warm contact discovered -> leads (nell)',
  '  speaking gig / press / podcast pitch -> visibility_targets (nova) or guests (nell)',
  '  content angle / hot take / quote -> content_ideas (cleo)',
  '  hypothesis with falsifiable outcome -> bets (marcus)',
  '  customer save / churn risk / expansion -> customers (maya) routed as a task',
  'task_type is one of: lead_signal, content_idea, task, customer_followup, visibility_target, guest_idea, bet_hypothesis, infra_change, random_thought.',
  'first_action is one short sentence describing what the agent does first.',
  'expected_completion_state is one short sentence describing what state would make Krish need to look at this again.',
  'If you cannot pick a primary_agent with confidence >= 0.7, populate needs_clarification with up to 2 short questions (one sentence each).',
  'suggested_concept_id should be of the form concept:<type>:<short-slug>.',
  'Output ONLY a JSON object matching this shape, no markdown:',
  '{"task_type":"...","primary_agent":"agatha|arlo|cleo|hunter|leo|marcus|maya|nell|nova|vera|zara","target_table":"tasks|leads|visibility_targets|guests|content_ideas|bets|customers","first_action":"...","expected_completion_state":"...","needs_clarification":[],"suggested_concept_id":"concept:type:slug","confidence":0.0}'
].join('\n');

const thread = Array.isArray(row.clarification_thread) ? row.clarification_thread : [];
const threadStr = thread.length === 0 ? '(no clarifications yet)' : thread.map(t => `[${t.by}] ${t.text}`).join('\n');

const user = `RAW INPUT:\n${row.raw_text}\n\nCLARIFICATION THREAD:\n${threadStr}`;

return [{ json: {
  inbox_id,
  raw_text: row.raw_text,
  anthropic_body: {
    model: 'claude-haiku-4-5', max_tokens: 700,
    system, messages: [{ role: 'user', content: user }],
  },
} }];

// Parses the classifier's answer. "Save classification" writes it over the
// stored Supabase credential (moved out of "Persist + route?" on 2026-10-03).
const carry = $('Load + classify').first().json;
const raw = $input.first().json;
const blocks = raw.content || [];
const text = blocks.map(b => b.text || '').join('').trim();

let cls = null;
try { const a = text.indexOf('{'); const b = text.lastIndexOf('}'); if (a >= 0 && b > a) cls = JSON.parse(text.slice(a, b + 1)); } catch { cls = null; }
if (!cls) cls = { needs_clarification: ['Classifier could not parse. Try rephrasing the inbox item.'], confidence: 0 };

const needsClarification = Array.isArray(cls.needs_clarification) && cls.needs_clarification.length > 0;
const nextStatus = needsClarification ? 'needs_clarification' : 'routing';
return [{ json: { inbox_id: carry.inbox_id, raw_text: carry.raw_text, cls, needsClarification, nextStatus } }];

// The classification was saved by "Save classification" just before this.
const __helpers = this.helpers;
async function __req(opts) { return __helpers.httpRequest({ ...opts, returnFullResponse: false }); }
const parsed = $('Parse classification').first().json;
const carry = { inbox_id: parsed.inbox_id, raw_text: parsed.raw_text };
const cls = parsed.cls;
const needsClarification = parsed.needsClarification;

let telegram_text = null;
if (needsClarification) {
  telegram_text = `Inbox needs you: "${(carry.raw_text || '').slice(0, 80)}". Questions: ${cls.needs_clarification.slice(0, 2).join(' | ')}`;
} else {
  // Fire router webhook.
  try {
    await __req({
      method: 'POST',
      url: 'https://krishraja10101.app.n8n.cloud/webhook/idea-route',
      headers: { 'Content-Type': 'application/json' },
      body: { inbox_id: carry.inbox_id }, json: true,
    });
  } catch (e) {
    telegram_text = `Inbox router failed for "${(carry.raw_text || '').slice(0, 80)}": ${(e.message || 'error').slice(0, 80)}`;
  }
}

return [{ json: { ok: true, inbox_id: carry.inbox_id, needs_clarification: needsClarification, classification: cls, telegram_text } }];
